<?php
$pdo=db();$contacts=$pdo->query("SELECT sg.id,sg.full_name,sg.relationship,sg.phone,sg.email,sg.consent_status,s.admission_no,s.first_name,s.last_name,l.user_id,u.full_name AS account_name,u.email AS account_email,u.active FROM student_guardians sg JOIN students s ON s.id=sg.student_id LEFT JOIN guardian_user_links l ON l.guardian_id=sg.id LEFT JOIN users u ON u.id=l.user_id ORDER BY sg.full_name,s.last_name,s.first_name")->fetchAll();$guardianUsers=$pdo->query("SELECT id,full_name,email,active FROM users WHERE role='Guardian' ORDER BY full_name")->fetchAll();
?>
<section class="panel info-panel"><h2>Guardian portal access</h2><p>Only link a guardian after the school has verified their authority and recorded granted consent. A guardian can see records for the learner contacts linked to that account. Guardian accounts must change their temporary password at first sign-in.</p></section>
<div class="academic-two-col"><section class="panel settings-panel"><h2>Create a guardian account</h2><form method="post" action="actions/guardian_account_save.php" class="student-form"><?= csrf_field() ?><input type="hidden" name="operation" value="create"><div class="form-grid"><label>Consented guardian contact<select name="guardian_id" required><option value="">Choose contact</option><?php foreach($contacts as $contact): if(!$contact['user_id']&&$contact['email']&&$contact['consent_status']==='Granted'): ?><option value="<?= (int)$contact['id'] ?>"><?= h($contact['full_name']) ?> · <?= h($contact['email']) ?> · <?= h($contact['first_name'].' '.$contact['last_name']) ?></option><?php endif; endforeach; ?></select></label><label>Temporary password<input type="password" name="password" minlength="12" required autocomplete="new-password"></label><label>Confirm password<input type="password" name="password_confirm" minlength="12" required autocomplete="new-password"></label></div><div class="form-actions"><button class="primary-button">Create guardian login</button></div></form></section>
<section class="panel settings-panel"><h2>Link another child</h2><form method="post" action="actions/guardian_account_save.php" class="student-form"><?= csrf_field() ?><input type="hidden" name="operation" value="link"><div class="form-grid"><label>Existing guardian account<select name="user_id" required><option value="">Choose account</option><?php foreach($guardianUsers as $account): if($account['active']): ?><option value="<?= (int)$account['id'] ?>"><?= h($account['full_name']) ?> · <?= h($account['email']) ?></option><?php endif; endforeach; ?></select></label><label>Consented contact to link<select name="guardian_id" required><option value="">Choose contact</option><?php foreach($contacts as $contact): if(!$contact['user_id']&&$contact['email']&&$contact['consent_status']==='Granted'): ?><option value="<?= (int)$contact['id'] ?>"><?= h($contact['full_name']) ?> · <?= h($contact['email']) ?> · <?= h($contact['first_name'].' '.$contact['last_name']) ?></option><?php endif; endforeach; ?></select></label></div><div class="form-actions"><button class="outline-button">Link child to account</button></div></form></section></div>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Guardian contacts and account links</h2><p>Portal access follows each individual guardian contact and consent state.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Guardian</th><th>Learner</th><th>Contact</th><th>Consent</th><th>Portal account</th><th>Status / action</th></tr></thead><tbody><?php foreach($contacts as $contact): ?><tr><td><?= h($contact['full_name']) ?><small class="muted-cell"><?= h($contact['relationship']) ?></small></td><td><?= h($contact['first_name'].' '.$contact['last_name']) ?> <small class="muted-cell"><?= h($contact['admission_no']) ?></small></td><td><?= h($contact['email']?:'No email') ?><small class="muted-cell"><?= h($contact['phone']) ?></small></td><td><span class="consent-pill <?= strtolower(h($contact['consent_status'])) ?>"><?= h($contact['consent_status']) ?></span></td><td><?= h($contact['account_name']?:'Not linked') ?><?= $contact['account_email']?'<small class="muted-cell">'.h($contact['account_email']).'</small>':'' ?></td><td><?php if($contact['user_id']): ?><span class="status-pill <?= $contact['active']?'':'inactive' ?>"><?= $contact['active']?'Active':'Disabled' ?></span><form method="post" action="actions/guardian_account_save.php"><?= csrf_field() ?><input type="hidden" name="operation" value="status"><input type="hidden" name="user_id" value="<?= (int)$contact['user_id'] ?>"><input type="hidden" name="active" value="<?= $contact['active']?0:1 ?>"><button class="text-button"><?= $contact['active']?'Disable account':'Enable account' ?></button></form><?php else: ?><span class="status-pill inactive">No access</span><?php endif; ?></td></tr><?php endforeach; if(!$contacts): ?><tr><td colspan="6" class="empty-cell">No guardian contacts have been recorded on learner records yet.</td></tr><?php endif; ?></tbody></table></div></section>
